from demo_kit import build
import json

def js(x): return json.dumps(x,ensure_ascii=False)
def ref(v): return ('Quran '+v,'https://quran.com/'+v.replace(':','/',1))
BASECSS='''
.chapter-nav{display:grid;gap:10px}.chapter-nav button{text-align:left}.stage{min-height:310px}.route{display:flex;gap:9px;flex-wrap:wrap;margin:20px 0}.route span{padding:8px 14px;background:var(--pale);border-radius:30px}.diagram{background:var(--pale);padding:25px;border-radius:14px;text-align:center}.diagram svg{display:block;margin:auto}.notearea{width:100%;min-height:80px}.caption{font-size:13px;color:var(--muted)}.ledger{font-variant-numeric:tabular-nums}.checkpoint{border-left:5px solid var(--accent);padding-left:18px}
'''

def guide(slug,kind,extra,steps,data,watchout):
    palettes={'stories':('#305e83','#e8f1fa'),'parables':('#684b8a','#f0eaf7'),'everyday-akhlaq-simulator':('#267458','#e8f5ed'),'halal-business-decisions':('#85502b','#fbefe3'),'conflict-resolution-scenarios':('#315e95','#eaf0fa'),'zakat-cases':('#72506a','#f6edf4')}
    accent,pale=palettes.get(slug,('#006d77','#def2ef'))
    return dict(next_steps=extra,build_steps=steps,stack=[f'TypeScript with Svelte and Vite for the {kind} interface. Ship static HTML and JavaScript first.','Versioned JSON content with schema validation. Use localStorage for optional on-device progress.','Add a Cloudflare Worker and D1 for signed-in progress only when users need cross-device access.'],data=data,watchout=watchout,css=BASECSS+f':root{{--accent:{accent};--pale:{pale}}}')

def cases(slug,title,description,items,kind='scenario',extra=None):
    body='''<div class="row"><span class="tag">3 fictional practice cases</span><span id="count"></span><button class="secondary" id="reset">Reset practice</button></div><div class="progress"><span id="bar"></span></div><div class="split"><aside class="chapter-nav" id="tabs" aria-label="Cases"></aside><article class="stage" id="stage"></article></div><p class="caption">Your choices and notes stay in this browser when storage is available. These fictional cases teach principles and do not issue personal rulings.</p>'''
    script='const items='+js(items)+';const key='+js(slug)+';'+r'''
let current=0,answers=store.get(key,{});if(!answers||typeof answers!=='object'||Array.isArray(answers))answers={};
function draw(){const done=Object.keys(answers).filter(k=>items[k]&&Number.isInteger(answers[k]?.choice)).length;$('#count').textContent=done+' / '+items.length+' cases explored';$('#bar').style.width=done/items.length*100+'%';$('#tabs').innerHTML=items.map((x,i)=>`<button class="secondary" data-tab="${i}" aria-pressed="${i===current}">${esc(x.name)} ${answers[i]?'✓':''}</button>`).join('');$$('[data-tab]').forEach(b=>b.onclick=()=>{current=+b.dataset.tab;draw()});const x=items[current],a=answers[current];$('#stage').innerHTML=`<div class="eyebrow">${esc(x.lens)}</div><h2>${esc(x.name)}</h2><p>${esc(x.scene)}</p><h3>${esc(x.question)}</h3><div class="choices">${x.choices.map((c,i)=>`<button data-choice="${i}" aria-pressed="${a?.choice===i}">${esc(c[0])}</button>`).join('')}</div><div id="result" aria-live="polite">${a?`<div class="feedback"><strong>${a.choice===x.best?'Principle supported':'Reconsider this response'}</strong><p>${esc(x.choices[a.choice]?.[1]||'Choose a response again.')}</p><p>${esc(x.principle)}</p><p class="source"><a href="${esc(x.url)}" target="_blank" rel="noopener">${esc(x.ref)}</a> · Source principle; the application is an editorial teaching example.</p></div><label>Plan one practical next step<textarea class="notearea" id="note" maxlength="600">${esc(a.note||'')}</textarea></label><p class="caption" id="noteStatus">Stored only on this device.</p>`:''}</div>`;$$('[data-choice]').forEach(b=>b.onclick=()=>{answers[current]={choice:+b.dataset.choice,note:answers[current]?.note||''};store.set(key,answers);draw()});if($('#note'))$('#note').oninput=e=>{answers[current].note=e.target.value;$('#noteStatus').textContent=store.set(key,answers)?'Saved on this device.':'Storage unavailable. Keep this page open to retain the note.'};}
$('#reset').onclick=()=>{answers={};store.set(key,answers);draw()};draw();
'''
    build(slug,title,'Decision simulators & ethical scenarios',description,body,script,sources=list(dict.fromkeys((x['ref'],x['url']) for x in items)),**guide(slug,kind,extra or ['Add reviewer-approved cases with multiple defensible responses.','Add a private weekly practice plan and exportable reflection notes.'],['Write fictional cases and separate the cited principle from the proposed response.','Review each explanation with a qualified subject reviewer. Record the review date.','Store choices as stable IDs. Test reset, revisit, mobile layout, and unavailable storage.','Publish a static beta. Measure completed cases without collecting private reflection text.'],f'Case(id, scene, learning_goal, choices[], preferred_response, explanation, source_ids[], reviewer_id, version). Attempt(case_id, choice_id, note, content_version). {kind.capitalize()} content needs editorial review.', 'The source links support general principles. The fictional outcomes are teaching examples. Contract details and personal circumstances require qualified advice.'))

cases('everyday-akhlaq-simulator','Everyday Akhlaq Simulator','Practice honesty, patience, and keeping promises through three ordinary decisions.',[
dict(name='The group chat',lens='Anger and restraint',scene='A classmate mocks your work in a group chat. You feel ready to reply with an insult.',question='What response gives you space to act fairly?',best=1,choices=[['Reply with a sharper insult.','A retaliatory insult increases the harm and leaves the original issue unresolved.'],['Pause, then explain the problem without insults.','Pausing creates room for restraint. A calm response can name the harm without repeating it.'],['Post an unrelated embarrassing photo.','Sharing an embarrassing photo adds another harm instead of addressing the comment.']],principle='Quran 3:134 commends restraint of anger and pardon. This does not require accepting ongoing harassment.',ref='Quran 3:134',url='https://quran.com/3/134'),
dict(name='The borrowed book',lens='Promises',scene='You promised to return a book today. You cannot reach your friend before closing time.',question='What is the most responsible next step?',best=0,choices=[['Contact your friend, explain, and agree a new return time.','You acknowledge the promise and make a concrete repair.'],['Wait until your friend asks.','Silence leaves your friend without the book or an explanation.'],['Say you already returned it.','An invented explanation hides the problem and creates another one.']],principle='Quran 17:34 calls for fulfilment of pledges. The communication plan is a practical application.',ref='Quran 17:34',url='https://quran.com/17/34'),
dict(name='The damaged charger',lens='Honesty and consent',scene='You damaged a sibling’s charger while borrowing it. They have not noticed.',question='How can you repair the situation?',best=2,choices=[['Hide it and hope someone else gets blamed.','Concealment transfers the harm to someone else.'],['Buy a replacement secretly and deny everything.','Replacing it may repair the object, but denying what happened avoids an honest conversation.'],['Explain what happened and agree how to replace or repair it.','Disclosure and an agreed repair respect your sibling’s property and choices.']],principle='Quran 4:29 prohibits wrongful consumption of another’s wealth and refers to mutual consent in trade. Respect for property informs this example.',ref='Quran 4:29',url='https://quran.com/4/29')])

cases('halal-business-decisions','Halal Business Decisions','Inspect fictional transactions, choose a response, and explain the principle behind it.',[
dict(name='The hidden defect',lens='Product disclosure',scene='Your shop has a laptop with a faulty charging port. A buyer offers the full advertised price.',question='What should happen before the buyer decides?',best=1,choices=[['Sell it without mentioning the port.','Hiding a known defect prevents an informed decision.'],['Disclose the fault and let the buyer decide on clear terms.','Disclosure lets the buyer assess the actual product and the price.'],['Describe it as perfect because it turns on.','The partial truth conceals a material problem.']],principle='Sahih al-Bukhari 2079 links truthful disclosure in a sale with blessing, and concealment with its loss.',ref='Sahih al-Bukhari 2079',url='https://sunnah.com/bukhari:2079'),
dict(name='The vague credit sale',lens='Written terms',scene='A supplier offers goods with payment later. The amount and payment date remain unclear.',question='What is the useful next step?',best=0,choices=[['Agree the amount and due date, then record the terms.','Clear terms reduce disagreement about what each party owes.'],['Accept now and settle the amount later.','Unresolved terms leave both parties exposed to disagreement.'],['Let one party change the price after delivery.','A unilateral price change undermines informed agreement.']],principle='Quran 2:282 gives directions for recording a debt for a specified term. This case does not evaluate every sale structure.',ref='Quran 2:282',url='https://quran.com/2/282'),
dict(name='The guaranteed loan return',lens='Riba and contract review',scene='A fictional lender proposes a cash loan with a required extra payment solely for the passage of time.',question='What should you do before proceeding?',best=2,choices=[['Rename the extra payment a gift in the contract.','A new label does not resolve the underlying condition.'],['Assume every guaranteed return has the same legal structure.','Different transactions require analysis of their actual terms.'],['Pause and obtain a qualified review of the loan and alternatives.','The required increment raises a riba concern. A qualified reviewer can examine the full transaction.']],principle='Quran 2:275 distinguishes permitted trade from prohibited riba. This example is not a certification of alternative products.',ref='Quran 2:275',url='https://quran.com/2/275')],kind='transaction review',extra=['Add a transaction worksheet for ownership, price, delivery, and payment obligations.','Ask qualified reviewers to annotate genuine differences between contract structures.','Add comparative case sets without automated halal certification.'])

cases('conflict-resolution-scenarios','Conflict Resolution Scenarios','Practice fact-checking, respectful disagreement, and fair mediation in fictional community cases.',[
dict(name='The missing donation',lens='Verify before accusing',scene='A message claims a volunteer took donation money. Nobody has checked the records.',question='What should the organizer do first?',best=1,choices=[['Forward the allegation to every group.','Forwarding spreads an unverified allegation and can harm the volunteer.'],['Check records and hear from the people involved privately.','Verification helps separate a bookkeeping error from an actual concern.'],['Assume the allegation must be false.','Automatic dismissal also avoids checking the evidence.']],principle='Quran 49:6 calls for verification of news in its stated context, to avoid harming people through ignorance.',ref='Quran 49:6',url='https://quran.com/49/6'),
dict(name='The meeting nickname',lens='Respectful disagreement',scene='Two committee members disagree about an event. One uses a humiliating nickname for the other.',question='How can the chair intervene?',best=0,choices=[['Stop the nickname and return to the proposal under discussion.','The chair can protect dignity while still allowing a substantive disagreement.'],['Join the joke to reduce tension.','Joining the joke normalizes humiliation.'],['Ban all disagreement.','Silencing all disagreement leaves the actual decision unresolved.']],principle='Quran 49:11 prohibits ridicule and offensive nicknames. Respectful debate can still examine the proposal.',ref='Quran 49:11',url='https://quran.com/49/11'),
dict(name='The shared hall',lens='Reconciliation with fairness',scene='Two study groups have been promised the same hall at the same time. Both claim priority.',question='What offers a fair path?',best=2,choices=[['Give the hall to the louder group.','Volume does not establish which agreement was made.'],['Ask the smaller group to accept blame.','Forced blame prevents a fair account of the booking mistake.'],['Hear both accounts, check bookings, and propose a fair arrangement.','Evidence and a mutually understood arrangement can repair the immediate dispute.']],principle='Quran 49:9-10 calls for reconciliation and justice in its context of conflict among believers. This scheduling example applies those broad values.',ref='Quran 49:9-10',url='https://quran.com/49/9-10')],kind='mediation practice',extra=['Add multi-step mediation with separate accounts from each fictional party.','Add facilitator notes and privacy controls for private groups.','Include boundaries for coercion and harm. Reconciliation must not pressure people into unsafe contact.'])

stories=[dict(name='Yusuf: recognition and pardon',ref='12:90-92',summary='Yusuf identifies himself to his brothers. They acknowledge wrongdoing. He responds with pardon and a prayer for forgiveness.',route=['Recognition','Acknowledgement','Pardon'],question='Which response is recorded after the brothers acknowledge their wrongdoing?',choices=['A declaration of pardon','A demand for revenge','A refusal to speak'],answer=0,why='Verse 12:92 records Yusuf’s response of pardon. The summary follows the passage and adds no imagined dialogue.'),dict(name='Musa: the search for knowledge',ref='18:60-66',summary='Musa travels with his assistant. After returning to the place where the fish was lost, they find a servant granted knowledge by Allah. Musa requests to learn.',route=['Journey','Return','Request to learn'],question='What does Musa request in verse 18:66?',choices=['An exact date for the journey','Permission to follow and learn','Ownership of a ship'],answer=1,why='Verse 18:66 describes a request to follow and learn. The passage does not supply the exact location of the meeting.'),dict(name='Yunus: prayer in distress',ref='21:87-88',summary='The passage recounts the man of the fish calling upon Allah in darkness, acknowledging wrongdoing. Allah responds and delivers him from distress.',route=['Distress','Prayer','Deliverance'],question='What follows the prayer in verse 21:88?',choices=['A stated geographical location','A new trade agreement','A response and deliverance from distress'],answer=2,why='Verse 21:88 describes the response and deliverance. This summary adds no physical depiction or invented scene.')]
story_body='''<div class="row"><span class="tag">3 source-linked chapters</span><button class="secondary" id="reset">Reset reading progress</button><span id="count"></span></div><div class="progress"><span id="bar"></span></div><div class="split"><aside id="tabs" class="chapter-nav" aria-label="Chapters"></aside><article id="stage"></article></div><p class="caption">Original paraphrases of the cited Quran passages. No quotations, imagined prophetic dialogue, or depictions. Progress saves on this browser when available.</p>'''
story_script='const chapters='+js(stories)+';'+r'''
const key='stories-of-the-prophets-explorer';let current=0,done=store.get(key,[]);if(!Array.isArray(done))done=[];done=done.filter(x=>Number.isInteger(x)&&chapters[x]);
function draw(){const x=chapters[current];$('#count').textContent=done.length+' / 3 understood';$('#bar').style.width=done.length/3*100+'%';$('#tabs').innerHTML=chapters.map((c,i)=>`<button class="secondary" data-tab="${i}" aria-pressed="${i===current}">${esc(c.name)} ${done.includes(i)?'✓':''}</button>`).join('');$$('[data-tab]').forEach(b=>b.onclick=()=>{current=+b.dataset.tab;draw()});$('#stage').innerHTML=`<h2>${esc(x.name)}</h2><div class="route">${x.route.map(t=>`<span>${esc(t)}</span>`).join('<span aria-hidden="true">→</span>')}</div><p class="checkpoint">${esc(x.summary)}</p><a target="_blank" rel="noopener" href="https://quran.com/${x.ref.replace(':','/')}">Read Quran ${x.ref} in context</a><h3>${esc(x.question)}</h3><div class="choices">${x.choices.map((c,i)=>`<button data-answer="${i}">${esc(c)}</button>`).join('')}</div><div class="feedback" id="feedback" aria-live="polite"></div>`;$$('[data-answer]').forEach(b=>b.onclick=()=>{const good=+b.dataset.answer===x.answer;$('#feedback').textContent=(good?'Correct. ':'Read the passage again. ')+x.why;if(good&&!done.includes(current)){done.push(current);store.set(key,done);$('#count').textContent=done.length+' / 3 understood';$('#bar').style.width=done.length/3*100+'%'}});}
$('#reset').onclick=()=>{done=[];store.set(key,done);draw()};draw();
'''
build('stories-of-the-prophets-explorer','Stories of the Prophets Explorer','Interactive stories & narrative learning','Read three Quranic narrative chapters, follow their sequence, and check your understanding.',story_body,story_script,sources=[ref(x['ref']) for x in stories],**guide('stories','chapter reader',['Add sequential chapters with verse context and age-specific comprehension questions.','Add licensed audio, bilingual reading, and a parent discussion mode.'],['Choose one narrative and divide it at source-supported boundaries.','Write summaries without invented dialogue. Link each claim to the passage.','Obtain a content review and permissions for any translations or audio.','Publish versioned chapters and save mastery by chapter version.'], 'Chapter(id, narrative_id, verse_range, summary, sequence[], questions[], source_edition, review_status). Mastery(chapter_id, version, completed_at).','These chapters use original paraphrases. A production reader must distinguish Quran text, translation, commentary, and editorial explanation.'))

parables=[dict(name='A good word and a tree',ref='14:24-26',summary='The passage compares a good word to a good tree with firm roots and branches reaching upward. It contrasts a bad word with an uprooted tree.',nodes=['Firm roots','Branches above','Fruit by permission'],question='What contrast does the passage make?',choices=['Rooted stability versus an uprooted tree','A prediction of crop prices','A map of a particular orchard'],answer=0,why='The diagram represents the comparison’s structure. It does not identify a botanical species or give a complete tafsir.'),dict(name='A grain and seven ears',ref='2:261',summary='The passage compares spending in Allah’s cause to one grain producing seven ears with one hundred grains in each. Allah multiplies further as He wills.',nodes=['One grain','Seven ears','100 in each ear'],question='What does 7 × 100 show in this illustration?',choices=['A guaranteed financial investment return','The number of chapters in the Quran','Seven hundred grains within the comparison'],answer=2,why='Seven times one hundred is seven hundred. The verse is about spending and divine reward, not a formula for cash investment returns.'),dict(name='The spider’s house',ref='29:41',summary='The passage compares those taking protectors besides Allah to a spider making a house, described as the frailest of houses.',nodes=['Taking protectors','Spider’s house','Frail shelter'],question='What is the focus of this comparison?',choices=['A biological claim about silk tensile strength','Misplaced reliance on protectors besides Allah','A rule about building materials'],answer=1,why='The passage concerns reliance and protection. The symbolic house is not a laboratory comparison of material strength.')]
pb=story_body.replace('3 source-linked chapters','3 interactive comparisons').replace('Reset reading progress','Reset studio').replace('Chapters','Parables').replace('Original paraphrases of the cited Quran passages. No quotations, imagined prophetic dialogue, or depictions.','Original paraphrases and editorial diagrams. Diagrams simplify the comparison and are not a complete tafsir.')
ps='const chapters='+js(parables)+';const key='+story_script.split('const key=')[1]
ps=ps.replace("'stories-of-the-prophets-explorer'","'quranic-parables-studio'")
ps=ps.replace("<div class=\"route\">${x.route.map(t=>`<span>${esc(t)}</span>`).join('<span aria-hidden=\"true\">→</span>')}</div>",'''<div class="diagram"><svg viewBox="0 0 600 160" role="img" aria-label="${esc(x.nodes.join(' leads to '))}"><path d="M110 65H490" fill="none" stroke="var(--accent)" stroke-width="3"/>${x.nodes.map((n,i)=>`<circle cx="${100+i*200}" cy="65" r="42" fill="white" stroke="var(--accent)" stroke-width="3"/><text x="${100+i*200}" y="72" text-anchor="middle" fill="var(--accent)" font-size="24">${i+1}</text><text x="${100+i*200}" y="140" text-anchor="middle" fill="var(--ink)" font-size="15">${esc(n)}</text>`).join('')}</svg><p class="caption">A conceptual diagram of the selected comparison.</p></div>''')
build('quranic-parables-studio','Quranic Parables Studio','Interactive stories & narrative learning','Switch between Quranic comparisons, inspect their structure, and test the limits of each illustration.',pb,ps,sources=[ref(x['ref']) for x in parables],**guide('parables','diagram studio',['Add reviewer-written tafsir notes with named editions and interpretation boundaries.','Add labelled diagram hotspots and private reflection prompts.'],['Define the objects and relationship in each cited comparison.','Draw accessible SVG diagrams with equivalent text descriptions.','Review every interpretation and distinguish text from editorial explanation.','Test comprehension questions and publish a small reviewed collection.'],'Parable(id, verse_range, objects[], relationships[], diagram_alt, editorial_summary, tafsir_refs[], questions[], review_version).','Each diagram is an editorial aid. A production studio should name its commentary sources and show where a diagram omits context.'))

zbody='''<div class="row"><span class="tag">Fictional asset classification lab</span><button class="secondary" id="reset">Reset case studies</button><span id="count"></span></div><div class="progress"><span id="bar"></span></div><label>Choose a case<select id="case"></select></label><div id="zstage"></div><p class="caption">Currency is illustrative units. All cases assume the relevant lunar-year condition is satisfied and the illustrative threshold is 5,000 units. This is not today’s nisab. No real metal price is used.</p>'''
zdata=[dict(name='Savings and ordinary possessions',scene='Amina has 12,000 cash, a personal-use bicycle worth 1,000, and ordinary clothing worth 500. Classify each item under the stated teaching assumptions.',assets=[['Cash',12000,True],['Personal-use bicycle',1000,False],['Ordinary clothing',500,False]],explain='This simplified case includes cash and excludes ordinary personal-use possessions. Businesses, investments, livestock, and crops need separate rules.'),dict(name='Personal gold jewellery',scene='Sara has 8,000 cash and personal-use gold jewellery valued at 4,000. Compare the two jewellery treatments below.',assets=[['Cash',8000,True],['Personal gold jewellery',4000,True]],explain='Scholars differ on qualifying personal-use jewellery. The toggle compares inclusion with exclusion, without deciding which applies to a person.'),dict(name='Repayments and savings',scene='Omar has 15,000 cash and a 10,000 interest-free long-term debt. Principal due over the next lunar year is 2,000.',assets=[['Cash',15000,True]],explain='NZF describes conditions for deducting certain repayments, including an impact on ability to repay. Compare a 2,000 deduction with no deduction. The full 10,000 debt is not deducted in this exercise.')]
zscript='const cases='+js(zdata)+';'+r'''
let current=0,done=store.get('zakat-case-study-simulator',[]);if(!Array.isArray(done))done=[];done=done.filter(i=>Number.isInteger(i)&&cases[i]);$('#case').innerHTML=cases.map((x,i)=>`<option value="${i}">${esc(x.name)}</option>`).join('');
function draw(){const x=cases[current];$('#count').textContent=done.length+' / 3 explored';$('#bar').style.width=done.length/3*100+'%';$('#zstage').innerHTML=`<h2>${esc(x.name)}</h2><p>${esc(x.scene)}</p><h3>Select the assets included in the teaching base</h3>${x.assets.map((a,i)=>`<label><input style="display:inline;width:auto" type="checkbox" data-asset="${i}" ${a[2]?'checked':''}> ${esc(a[0])} · ${a[1].toLocaleString()} units</label>`).join('')}${current===2?'<label>Debt assumption<select id="debt"><option value="0">No debt deduction</option><option value="2000">Deduct 2,000 of forthcoming principal, if the stated conditions apply</option></select></label>':''}<button id="explore">Explore this selection</button><div id="zresult" class="feedback" aria-live="polite"></div><p>${esc(x.explain)}</p><p class="source"><a href="https://www.nzf.org.au/blog/zakat-guide-for-individuals-families/" target="_blank" rel="noopener">NZF individual guide: assets, jewellery and rate</a> · <a href="https://nzf.org.uk/knowledge/which-debts-can-be-deducted-from-my-zakat-calculation/" target="_blank" rel="noopener">NZF debt conditions</a></p>`;$('#explore').onclick=calc;$$('[data-asset]').forEach(b=>b.onchange=()=>{$('#zresult').textContent='Selection changed. Explore this selection to update the comparison.'});if($('#debt'))$('#debt').onchange=()=>{$('#zresult').textContent='Debt assumption changed. Explore again.'};}
function calc(){const x=cases[current],gross=$$('[data-asset]:checked').reduce((s,b)=>s+x.assets[+b.dataset.asset][1],0),debt=Number($('#debt')?.value||0),base=Math.max(0,gross-debt),amount=base>=5000?base*.025:0;const misclassified=current===0&&$$('[data-asset]').some(b=>b.checked!==x.assets[+b.dataset.asset][2])||current>0&&!$('[data-asset="0"]').checked;$('#zresult').innerHTML=`<strong>${amount.toFixed(2)} illustrative units</strong><p>Selected assets ${gross.toLocaleString()} − selected deduction ${debt.toLocaleString()} = ${base.toLocaleString()} units.</p><p>${base>=5000?`${base.toLocaleString()} × 2.5% = ${amount.toFixed(2)}`:'Below the fixed teaching threshold of 5,000, so this model produces 0.'}</p><p>${misclassified?'Classification needs review: cash belongs in the base; the bicycle and ordinary clothing do not under this case’s assumptions. This result shows your selection only.':'This selection follows one of the stated teaching assumptions.'}</p>`;if(!done.includes(current)){done.push(current);store.set('zakat-case-study-simulator',done);$('#count').textContent=done.length+' / 3 explored';$('#bar').style.width=done.length/3*100+'%'}}
$('#case').onchange=e=>{current=+e.target.value;draw()};$('#reset').onclick=()=>{done=[];current=0;$('#case').value='0';store.set('zakat-case-study-simulator',done);draw()};draw();
'''
build('zakat-case-study-simulator','Zakat Case Study Simulator','Decision simulators & ethical scenarios','Classify fictional assets and compare how stated assumptions change the arithmetic.',zbody,zscript,sources=[('NZF Australia individual and family guide','https://www.nzf.org.au/blog/zakat-guide-for-individuals-families/'),('NZF UK deductible debt conditions','https://nzf.org.uk/knowledge/which-debts-can-be-deducted-from-my-zakat-calculation/')],**guide('zakat-cases','asset classification lab',['Add expert-reviewed cases for trade stock, receivables, and mixed assets.','Add named scholarly methodology packs with dated reviews.','Add worked solutions and a teacher-led comparison mode.'],['Define each fictional balance sheet and the exact teaching assumptions.','Represent money as integer minor units. Version rates and methodology rules.','Test classification, threshold boundaries, deductions, and worked examples.','Obtain qualified review before adding personal calculations or live metal prices.'],'Case(id, assets[], debt_schedule, hawl_assumption, fixed_nisab, methodology_ids[], expected_classifications[]). Methodology(id, asset_rules, debt_conditions, reviewer, version).','These case studies explain calculation differences. They do not determine personal liability. The 5,000 threshold is a fixed teaching value.'))

print('Built six story and scenario demos.')
